CREATE TABLE IF NOT EXISTS fec_va_house_candidates (
    cand_id             TEXT PRIMARY KEY,
    name                TEXT,
    party               TEXT,
    district            INTEGER,
    ici                 TEXT,
    status              TEXT,
    committee_id        TEXT,
    cycle               INTEGER DEFAULT 2026,
    total_receipts      REAL,
    ind_contributions   REAL,
    total_disbursements REAL,
