    loaded_at           TEXT
);
CREATE INDEX IF NOT EXISTS idx_fvhc_dist  ON fec_va_house_candidates(district);
CREATE INDEX IF NOT EXISTS idx_fvhc_party ON fec_va_house_candidates(party);

